import numpy as np
from scipy.spatial.transform import Rotation

# Test case: left-handed matrix (negative determinant)
m = np.eye(3)
m[0, 0] = -1

try:
    result = Rotation.from_matrix(m).as_matrix()
    probe('left_handed_accepted', 1)  # 1 means it was accepted (no exception)
    for i in range(3):
        for j in range(3):
            probe(f'result[{i},{j}]', result[i, j])
except ValueError as e:
    probe('left_handed_accepted', 0)  # 0 means it was rejected
